python
def risingLabelsPeakTicket(readings, k):
    a=readings
    out=[]
    from bisect import bisect_left
    tails=[]
    for x in a:
        i=bisect_left(tails,x)
        if i==len(tails): tails.append(x)
        else: tails[i]=x
        out.append(i+1)
    return max(out,default=0)


java
class Solution {
  public int risingLabelsPeakTicket(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {int[]tails=new int[a.length];int length=0;for(int x:a){int l=0,r=length;while(l<r){int m=(l+r)/2;if(tails[m]<x)l=m+1;else r=m;}tails[l]=x;if(l==length)length++;out.add(l+1);}}
    int answer=out.isEmpty()?0:out.get(0);for(int x:out)answer=Math.max(answer,x);return answer;
  }
}
